-- +goose Up
-- 016_ede_012_confidence_reframe.sql
-- EDE-012: confidence scoring metrics relabeled from outcome-calibration to
-- shrinkage-formula behavior under single-outcome-class conditions.
-- The methodology document's §4.5 headline metrics (Brier 0.0018, ECE 0.031)
-- were presented as evidence of empirical calibration when the corpus they
-- measure contains only passing fixtures. A refit attempt (2026-07-30)
-- confirmed no probability can be fitted: the outcome is 99.6% one class
-- across 52,053 observations.

INSERT INTO ede_events (ede_id, event_date, commit_ref, category, severity, title, status, attribution, protocols_affected, confidence_impact, resolution, bayesian_note, correction_action, prevention_rule, authoritative_source) VALUES ('EDE-012', '2026-07-31', 'hermes/docs-confidence-reframe', 'scoring_calibration', 'significant', 'Confidence metrics relabeled from outcome-calibration to fixture-agreement under synthetic degradation', 'closed', 'Both', '[]'::jsonb, 'Methodology §4.5 presented Brier 0.0018 and ECE 0.031 as evidence of empirical calibration when all 129 test cases pass (single outcome class). The metrics measure shrinkage-formula agreement with a constant outcome, not calibration against diverging outcomes. A refit against real scan outcomes (Claude Science, 2026-07-30) confirmed: the outcome a probability would predict is 99.6% one class across 52,053 observations — a logistic fit gained within the noise band, and a gradient-boosted alternative performed materially worse than a constant predictor. The stored value is a severity encoding (pass/warning/fail/indeterminate on a 0-1 scale), not a probability.', 'Code renamed protocolRawConfidence → protocolVerdictSeverity (c89ece6f3, PR #232) with the negative result recorded in the function comment. Methodology §4.5 rewritten: metrics relabeled as shrinkage-formula behavior under single-outcome-class conditions; conclusion reworded from "conservatively calibrated" to "conservatively shrinkage-weighted"; field replication result (99.6% across 52,053 pairs on 275 domains over 167 days) added as the engine''s real-world stability number. FEATURE_INVENTORY.md updated to match.', 'The mislabel originated in the original calibration framework implementation (pre-EDE-011). EDE-011 corrected the formula''s name (shrinkage, not Bayesian) but left the validation section''s framing intact — the metrics were still presented as calibration evidence rather than formula-behavior measurements. Claude Science''s independent refit attempt provided the empirical basis for the correction: the negative result IS the finding, and it ships as naming (severity encoding) rather than fitting (probability calibration).', 'Methodology §4.5 rewritten (metrics relabeled, limitation restated, conclusion reworded, field replication added). FEATURE_INVENTORY.md updated. Code comment in analysis_confidence.go:62-69 carries the negative result and a "must never be renamed back to a probability" instruction.', 'Metrics derived from a single-outcome-class corpus must be labeled as formula-behavior measurements, not calibration evidence. Any future calibration claim requires a corpus containing both passing and failing outcomes, and the refit must demonstrate skill above the noise band against the base rate.', 'Claude Science refit (2026-07-30): logistic regression skill +0.004 (inside noise band), gradient-boosted model Brier 0.005361 (above band upper bound 0.004228, worse than constant). Field replication: 99.6% across 52,053 consecutive pairs on 275 domains, 2026-02-08 to 2026-07-26.') ON CONFLICT (ede_id) DO NOTHING;
